              }
              60% {
                opacity: 1;
                transform: translateY(-2px) scale(1.04);
              }
              100% {
                opacity: 1;
                transform: translateY(0) scale(1);
              }
            }
            @keyframes tooltip-pop-bottom {
              0% {
                opacity: 0;
                transform: translateY(-8px) scale(0.65);
              }
              60% {
                opacity: 1;
                transform: translateY(2px) scale(1.04);
              }
              100% {
                opacity: 1;
                transform: translateY(0) scale(1);
              }
            }
            @keyframes tooltip-pop-left {
              0% {
                opacity: 0;
                transform: translateX(8px) scale(0.65);
              }
              60% {
                opacity: 1;
                transform: translateX(-2px) scale(1.04);
              }
              100% {
                opacity: 1;
                transform: translateX(0) scale(1);
              }
            }
            @keyframes tooltip-pop-right {
              0% {
                opacity: 0;
                transform: translateX(-8px) scale(0.65);
              }
              60% {
                opacity: 1;
                transform: translateX(2px) scale(1.04);
              }
              100% {
                opacity: 1;
                transform: translateX(0) scale(1);
              }
            }
            @media (prefers-reduced-motion: reduce) {
              * {
                animation: none !important;
              }
            }
          `}</style>
        )}
        {isArrowEmerge && (
          <style>{`
            @keyframes tooltip-emerge-top {
              0% {
                opacity: 0;
                transform: translateY(12px) scale(0.08);
              }
              25% {
                opacity: 1;
              }
              100% {
                opacity: 1;
                transform: translateY(0) scale(1);
              }
            }
            @keyframes tooltip-emerge-bottom {
              0% {
                opacity: 0;
                transform: translateY(-12px) scale(0.08);
              }
              25% {
                opacity: 1;
              }
              100% {
                opacity: 1;
                transform: translateY(0) scale(1);
              }
